// Tarot of the day: a card drawn each morning from the 78, upright or
// reversed, painted fresh in the deck style you pick, with a short reading.
// For fun. Needs an OpenAI API key.
import { apiKey, askJson, paint, pictureFor, sizeFor, dayKey } from './ai'

const MAJOR = 'The Fool,The Magician,The High Priestess,The Empress,The Emperor,The Hierophant,The Lovers,The Chariot,Strength,The Hermit,Wheel of Fortune,Justice,The Hanged Man,Death,Temperance,The Devil,The Tower,The Star,The Moon,The Sun,Judgement,The World'.split(',')
const RANKS = 'Ace,Two,Three,Four,Five,Six,Seven,Eight,Nine,Ten,Page,Knight,Queen,King'.split(',')
const SUITS = 'Wands,Cups,Swords,Pentacles'.split(',')

function cardOf(index: number) {
  if (index < 22) return MAJOR[index]
  const i = index - 22
  return `${RANKS[i % 14]} of ${SUITS[Math.floor(i / 14)]}`
}

// The same card all day, a different one each day.
function draw(day: string) {
  let h = 2166136261
  for (let i = 0; i < day.length; i++) h = Math.imul(h ^ day.charCodeAt(i), 16777619) >>> 0
  return { card: cardOf(h % 78), reversed: ((h >>> 8) & 3) === 0 }
}

const DECKS: Record<string, string> = {
  nouveau: 'an Art Nouveau tarot card, flowing lines, muted gold, sage and rose, an ornate border',
  marseille: 'a Tarot de Marseille woodcut, flat primary colors, bold black outlines',
  celestial: 'a celestial tarot card, gold leaf on deep midnight blue, stars and fine linework',
  botanical: 'a botanical watercolor tarot card, plants and creatures, soft paper texture',
}

const SYSTEM = `You read one tarot card a day for someone who keeps a picture frame on their wall.
Be warm, playful and encouraging, practical rather than fatalistic, and never about health, money decisions or
predictions of harm. Answer JSON only:
{"keywords": ["three single words for the card's meaning"], "reading": "the reading, 60 to 85 words",
"art": "a prompt for the card's illustration, 40 to 70 words: its traditional symbols and figures, no text"}`

export function get(app: FrameOSApp, context: FrameOSContext) {
  const today = dayKey(new Date())
  return pictureFor(app, 'reading', today, 'ai-scenes/tarot-of-the-day', (path) => {
    const key = apiKey()
    const { card, reversed } = draw(today)
    const focus = String(app.config.focus || 'the day ahead')
    const reading = askJson(key, String(app.config.textModel || 'gpt-6.1-terra'), SYSTEM, `The card is ${card}${reversed ? ', reversed' : ''}. Focus the reading on ${focus}.`)
    const deck = DECKS[String(app.config.deck)] || DECKS.nouveau
    const width = context.targetWidth || context.imageWidth || app.frame.width
    const height = context.targetHeight || context.imageHeight || app.frame.height
    const model = String(app.config.imageModel || 'gpt-image-2')
    const art = `${reading.art}\n\nThe card ${card}${reversed ? ' (the figure need not be upside down)' : ''}, painted as ${deck}. Fill the whole picture with the card's art; no title, numbers, letters or text.`
    paint(key, model, art, sizeFor(model, width, height, app.frame.embedded), path, app.frame.embedded)
    return {
      card,
      reversed,
      keywords: Array.isArray(reading.keywords) ? reading.keywords.slice(0, 3).map(String) : [],
      reading: String(reading.reading || ''),
    }
  })
}

